import{_ as e,o as s,c as p,a2 as i}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_cover.png",t="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_01_system_architecture.png",c="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_02_lifecycle.png",l="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_03_load_pipeline.png",o="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_04_modes.png",r="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_05_runtime_interfaces.png",d="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_06_save_pipeline.png",y=JSON.parse('{"title":"一张 PGM 地图怎样进入 Nav2？拆解 nav2_map_server 调用全数据流","description":"很多人第一次接触 Nav2，会把静态地图理解成一张黑白图片。","frontmatter":{"title":"一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流","description":"很多人第一次接触 Nav2，会把静态地图理解成一张黑白图片。","date":"2026-07-15","section":"一 · 架构与启动","readingTime":12,"source":"2026-07-15/nav2_map_server_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-15/nav2_map_server_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-map-server-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流"}],["meta",{"property":"og:description","content":"很多人第一次接触 Nav2，会把静态地图理解成一张黑白图片。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-map-server-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-15"}],["meta",{"name":"twitter:title","content":"一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流"}],["meta",{"name":"twitter:description","content":"很多人第一次接触 Nav2，会把静态地图理解成一张黑白图片。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_map_server_cover.png"}]],"prev":{"text":"Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流","link":"/nav2/nav2-lifecycle-manager-full-dataflow"},"next":{"text":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解","link":"/nav2/nav2-global-local-map-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-map-server-full-dataflow.md","filePath":"nav2/nav2-map-server-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-map-server-full-dataflow.md"};function m(u,a,v,g,_,b){return s(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="一张-pgm-地图怎样进入-nav2-拆解-nav2-map-server-调用全数据流" tabindex="-1">一张 PGM 地图怎样进入 Nav2？拆解 <code>nav2_map_server</code> 调用全数据流 <a class="header-anchor" href="#一张-pgm-地图怎样进入-nav2-拆解-nav2-map-server-调用全数据流" aria-label="Permalink to &quot;一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流&quot;">​</a></h1><p><img src="'+n+`" alt="封面：Nav2 的地图翻译官"></p><p>很多人第一次接触 Nav2，会把静态地图理解成一张黑白图片。</p><p>但规划器和定位器不能直接理解 PGM 或 PNG。它们需要知道每个像素对应多少米、地图原点位于哪里、黑白是否反转、什么灰度算障碍物，以及整张地图属于哪个坐标系。</p><p><code>nav2_map_server</code> 的工作，就是把磁盘上的“图片和说明书”翻译成 ROS 2 可以传输的 <code>nav_msgs/msg/OccupancyGrid</code>，并在运行期提供读取、换图和保存能力。</p><p>本文从启动参数 <code>yaml_filename</code> 出发，完整追踪：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YAML 元数据</span></span>
<span class="line"><span>→ 图像像素</span></span>
<span class="line"><span>→ OccupancyGrid</span></span>
<span class="line"><span>→ /map</span></span>
<span class="line"><span>→ AMCL／Global Costmap／RViz2</span></span></code></pre></div><p>同时再反向追踪 <code>MapSaver</code> 怎样把 <code>/map</code> 写回图片和 YAML。</p><p><img src="`+t+`" alt="图 1：nav2_map_server 系统调用总览"></p><h2 id="一、先给结论-这个包里不只有-mapserver" tabindex="-1">一、先给结论：这个包里不只有 MapServer <a class="header-anchor" href="#一、先给结论-这个包里不只有-mapserver" aria-label="Permalink to &quot;一、先给结论：这个包里不只有 MapServer&quot;">​</a></h2><p><code>nav2_map_server</code> 包含三类 Lifecycle 节点和一套地图 I/O 库。</p><h3 id="_1-1-mapserver" tabindex="-1">1.1 MapServer <a class="header-anchor" href="#_1-1-mapserver" aria-label="Permalink to &quot;1.1 MapServer&quot;">​</a></h3><p>读取静态地图，缓存 <code>OccupancyGrid</code>，发布地图 Topic，并提供 GetMap 和 LoadMap 服务。</p><h3 id="_1-2-mapsaver" tabindex="-1">1.2 MapSaver <a class="header-anchor" href="#_1-2-mapsaver" aria-label="Permalink to &quot;1.2 MapSaver&quot;">​</a></h3><p>临时订阅地图 Topic，把收到的 <code>OccupancyGrid</code> 写成图片和 YAML。</p><h3 id="_1-3-costmapfilterinfoserver" tabindex="-1">1.3 CostmapFilterInfoServer <a class="header-anchor" href="#_1-3-costmapfilterinfoserver" aria-label="Permalink to &quot;1.3 CostmapFilterInfoServer&quot;">​</a></h3><p>发布代价地图过滤器元数据，告诉 Costmap Filter 去哪里订阅 mask，以及怎样把 mask 数值换算成过滤器参数。</p><h3 id="_1-4-map-io" tabindex="-1">1.4 <code>map_io</code> <a class="header-anchor" href="#_1-4-map-io" aria-label="Permalink to &quot;1.4 \`map_io\`&quot;">​</a></h3><p><code>map_io</code> 是不依赖具体节点的转换库，完成 YAML、图片和 <code>OccupancyGrid</code> 之间的双向转换。</p><p>最核心的数据闭环是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘地图 → map_io → MapServer 缓存 → /map</span></span>
<span class="line"><span>   ↑                                  ↓</span></span>
<span class="line"><span>图片 + YAML ← map_io ← MapSaver ← OccupancyGrid</span></span></code></pre></div><h2 id="二、地图其实有三层" tabindex="-1">二、地图其实有三层 <a class="header-anchor" href="#二、地图其实有三层" aria-label="Permalink to &quot;二、地图其实有三层&quot;">​</a></h2><p>理解 Map Server，首先要分清三种完全不同的数据形态。</p><h3 id="_2-1-yaml-元数据层" tabindex="-1">2.1 YAML 元数据层 <a class="header-anchor" href="#_2-1-yaml-元数据层" aria-label="Permalink to &quot;2.1 YAML 元数据层&quot;">​</a></h3><p>典型地图 YAML 包含：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">map.pgm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trinary</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">resolution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.05</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">negate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">occupied_thresh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.65</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">free_thresh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span></span></code></pre></div><p>这里没有任何栅格数组。它只描述如何解释图片：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>image              图片路径</span></span>
<span class="line"><span>resolution         每个像素对应的米数</span></span>
<span class="line"><span>origin             地图左下角在世界坐标中的 x、y、yaw</span></span>
<span class="line"><span>negate             是否翻转黑白的占用含义</span></span>
<span class="line"><span>occupied_thresh    判定占用的概率阈值</span></span>
<span class="line"><span>free_thresh        判定空闲的概率阈值</span></span>
<span class="line"><span>mode               trinary／scale／raw</span></span></code></pre></div><p>相对 <code>image</code> 路径不是相对当前终端目录，而是相对 YAML 文件所在目录展开。YAML 路径本身以 <code>~/</code> 开头时，<code>map_io</code> 会尝试使用 <code>HOME</code> 环境变量展开。</p><h3 id="_2-2-图像像素层" tabindex="-1">2.2 图像像素层 <a class="header-anchor" href="#_2-2-图像像素层" aria-label="Permalink to &quot;2.2 图像像素层&quot;">​</a></h3><p>PGM、PNG 或 BMP 提供宽、高和每个像素的颜色。GraphicsMagick 负责解码图片，<code>map_io</code> 再把 RGB 和可选 Alpha 转成亮度与占用概率。</p><p>图像坐标原点通常在左上角，<code>OccupancyGrid</code> 的数据布局则按地图左下角语义组织。因此读写时都使用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data[width </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (height </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x]</span></span></code></pre></div><p>这个 Y 轴翻转是“图片看起来正确，但 RViz2 地图上下颠倒”问题的关键边界。</p><h3 id="_2-3-occupancygrid-消息层" tabindex="-1">2.3 OccupancyGrid 消息层 <a class="header-anchor" href="#_2-3-occupancygrid-消息层" aria-label="Permalink to &quot;2.3 OccupancyGrid 消息层&quot;">​</a></h3><p>Nav2 真正消费的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>header.frame_id／stamp</span></span>
<span class="line"><span>info.map_load_time</span></span>
<span class="line"><span>info.resolution</span></span>
<span class="line"><span>info.width／height</span></span>
<span class="line"><span>info.origin</span></span>
<span class="line"><span>data[]</span></span></code></pre></div><p><code>data</code> 中常见值为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0    空闲</span></span>
<span class="line"><span>100  占用</span></span>
<span class="line"><span>-1   未知</span></span></code></pre></div><p>从这一层开始，AMCL、StaticLayer、RViz2 和业务节点不再关心原始图片格式。</p><h2 id="三、lifecycle-决定-文件已读-和-地图可用-不是一回事" tabindex="-1">三、Lifecycle 决定“文件已读”和“地图可用”不是一回事 <a class="header-anchor" href="#三、lifecycle-决定-文件已读-和-地图可用-不是一回事" aria-label="Permalink to &quot;三、Lifecycle 决定“文件已读”和“地图可用”不是一回事&quot;">​</a></h2><p>Map Server 继承 <code>nav2_util::LifecycleNode</code>。它必须经过 configure 和 activate，才成为完整可用的地图服务。</p><p><img src="`+c+`" alt="图 2：Map Server Lifecycle 数据流程"></p><h3 id="_3-1-构造阶段" tabindex="-1">3.1 构造阶段 <a class="header-anchor" href="#_3-1-构造阶段" aria-label="Permalink to &quot;3.1 构造阶段&quot;">​</a></h3><p>构造函数只声明三个参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yaml_filename</span></span>
<span class="line"><span>topic_name，默认 map</span></span>
<span class="line"><span>frame_id，默认 map</span></span></code></pre></div><p>此时没有读取地图，没有创建 <code>/map</code> Publisher，也没有 GetMap／LoadMap 服务。</p><h3 id="_3-2-configure-阶段" tabindex="-1">3.2 CONFIGURE 阶段 <a class="header-anchor" href="#_3-2-configure-阶段" aria-label="Permalink to &quot;3.2 CONFIGURE 阶段&quot;">​</a></h3><p><code>on_configure()</code> 读取参数。如果 <code>yaml_filename</code> 非空，就立即调用 <code>loadMapFromYaml()</code>，把结果写入成员缓存 <code>msg_</code>，并设置 <code>map_available_=true</code>。</p><p>加载失败不是“先启动再说”。配置回调会抛出异常，Lifecycle configure 失败，上层 Lifecycle Manager 也无法完成整组节点启动。</p><p>如果 <code>yaml_filename</code> 为空，configure 仍然可以成功。节点创建服务和 Publisher，但暂时没有地图，等待运行期通过 <code>map_server/load_map</code> 加载。</p><p>随后创建三项 ROS 接口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;node_name&gt;/map       nav_msgs/srv/GetMap</span></span>
<span class="line"><span>&lt;node_name&gt;/load_map  nav2_msgs/srv/LoadMap</span></span>
<span class="line"><span>topic_name            nav_msgs/msg/OccupancyGrid</span></span></code></pre></div><h3 id="_3-3-activate-阶段" tabindex="-1">3.3 ACTIVATE 阶段 <a class="header-anchor" href="#_3-3-activate-阶段" aria-label="Permalink to &quot;3.3 ACTIVATE 阶段&quot;">​</a></h3><p><code>on_activate()</code> 先激活 Lifecycle Publisher。如果已经有缓存地图，就立即发布一次；没有地图则只进入 active，继续等待 LoadMap。</p><p>之后调用 <code>createBond()</code>，让 Lifecycle Manager 可以监控 Map Server 存活状态。</p><h3 id="_3-4-deactivate-和-cleanup" tabindex="-1">3.4 DEACTIVATE 和 CLEANUP <a class="header-anchor" href="#_3-4-deactivate-和-cleanup" aria-label="Permalink to &quot;3.4 DEACTIVATE 和 CLEANUP&quot;">​</a></h3><p>deactivate 会停止 Publisher 并销毁 Bond。cleanup 会释放 Publisher、两个服务，清空 <code>msg_</code> 并把 <code>map_available_</code> 重置为 false。</p><p>所以，cleanup 后不是“地图仍在内存里但不发布”，而是整份运行时地图缓存已经被清掉。</p><h2 id="四、加载主链-yaml-怎样变成-occupancygrid" tabindex="-1">四、加载主链：YAML 怎样变成 OccupancyGrid <a class="header-anchor" href="#四、加载主链-yaml-怎样变成-occupancygrid" aria-label="Permalink to &quot;四、加载主链：YAML 怎样变成 OccupancyGrid&quot;">​</a></h2><p><code>loadMapFromYaml()</code> 把错误分成元数据错误和图像数据错误，再串联两个核心步骤。</p><p><img src="`+l+`" alt="图 3：YAML、图像和 OccupancyGrid 转换链"></p><h3 id="_4-1-loadmapyaml-解析地图说明书" tabindex="-1">4.1 loadMapYaml：解析地图说明书 <a class="header-anchor" href="#_4-1-loadmapyaml-解析地图说明书" aria-label="Permalink to &quot;4.1 loadMapYaml：解析地图说明书&quot;">​</a></h3><p>这个函数读取 <code>image</code>、<code>resolution</code>、<code>origin</code>、两个阈值、<code>mode</code> 和 <code>negate</code>。</p><p><code>origin</code> 必须恰好包含三个元素。<code>mode</code> 未填写时默认 <code>trinary</code>。<code>negate</code> 同时兼容整数和布尔写法。</p><p>YAML 文件无法打开、字段缺失、类型错误或 mode 非法，都会被归类为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INVALID_MAP_METADATA</span></span></code></pre></div><h3 id="_4-2-loadmapfromfile-逐像素生成地图" tabindex="-1">4.2 loadMapFromFile：逐像素生成地图 <a class="header-anchor" href="#_4-2-loadmapfromfile-逐像素生成地图" aria-label="Permalink to &quot;4.2 loadMapFromFile：逐像素生成地图&quot;">​</a></h3><p>GraphicsMagick 读出图片后，宽高直接成为 <code>OccupancyGrid.info.width</code> 和 <code>height</code>；分辨率与原点来自 YAML。</p><p>每个像素先计算 RGB 平均亮度 <code>shade</code>，范围为 0.0 到 1.0。然后根据 <code>negate</code> 计算占用程度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>negate = false：occ = 1.0 - shade</span></span>
<span class="line"><span>negate = true： occ = shade</span></span></code></pre></div><p>默认 <code>negate=false</code> 时，黑色亮度低，因此占用程度高；白色亮度高，因此占用程度低。</p><p>图片无法读取或像素转换抛出异常，会被归类为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INVALID_MAP_DATA</span></span></code></pre></div><h3 id="_4-3-mapserver-再修正-header" tabindex="-1">4.3 MapServer 再修正 Header <a class="header-anchor" href="#_4-3-mapserver-再修正-header" aria-label="Permalink to &quot;4.3 MapServer 再修正 Header&quot;">​</a></h3><p><code>map_io</code> 不是 ROS Node，只能用系统时钟临时填写时间，并默认使用 <code>map</code> frame。</p><p>加载回到 <code>MapServer</code> 后，<code>updateMsgHeader()</code> 会使用节点自己的 <code>now()</code> 更新 <code>map_load_time</code> 和消息时间戳，并用 <code>frame_id</code> 参数覆盖 frame。</p><p>这一步对仿真时间尤其重要：最终发布的地图 Header 由节点时钟决定，而不是保留 I/O 库最初写入的系统时间。</p><h2 id="五、三种地图模式不是显示风格-而是数据语义" tabindex="-1">五、三种地图模式不是显示风格，而是数据语义 <a class="header-anchor" href="#五、三种地图模式不是显示风格-而是数据语义" aria-label="Permalink to &quot;五、三种地图模式不是显示风格，而是数据语义&quot;">​</a></h2><p>同一个灰度像素，在 <code>trinary</code>、<code>scale</code> 和 <code>raw</code> 下可能得到完全不同的栅格值。</p><p><img src="`+o+`" alt="图 4：trinary、scale 和 raw 模式"></p><h3 id="_5-1-trinary-三值地图" tabindex="-1">5.1 Trinary：三值地图 <a class="header-anchor" href="#_5-1-trinary-三值地图" aria-label="Permalink to &quot;5.1 Trinary：三值地图&quot;">​</a></h3><p>这是默认模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>occ &gt; occupied_thresh → 100</span></span>
<span class="line"><span>occ &lt; free_thresh     → 0</span></span>
<span class="line"><span>中间区域              → -1</span></span></code></pre></div><p>它适合传统静态导航地图：明确分为空闲、障碍和未知三类。</p><p>Trinary 读取带透明通道的图片时，会把 Alpha 也加入颜色平均。源码特别提醒：GraphicsMagick 的 Alpha 数值语义与直觉相反，高值表示透明。</p><h3 id="_5-2-scale-保留概率梯度" tabindex="-1">5.2 Scale：保留概率梯度 <a class="header-anchor" href="#_5-2-scale-保留概率梯度" aria-label="Permalink to &quot;5.2 Scale：保留概率梯度&quot;">​</a></h3><p>Scale 在两个阈值之间按比例映射到 1～99，而不是全部变成 unknown。透明像素直接变为 -1。</p><p>这种模式需要图片格式支持透明通道，因此保存时默认选择 PNG。若强制使用 PGM 或 JPEG，代码会发出“Scale 需要透明度”的警告。</p><h3 id="_5-3-raw-直接保留低范围像素值" tabindex="-1">5.3 Raw：直接保留低范围像素值 <a class="header-anchor" href="#_5-3-raw-直接保留低范围像素值" aria-label="Permalink to &quot;5.3 Raw：直接保留低范围像素值&quot;">​</a></h3><p>Raw 计算 <code>round(shade × 255)</code>。只有结果处于 0～100 时才直接写入；超过这个范围则标为 -1。</p><p>它不是“把黑色当 100”的概率转换，也不经过 free／occupied 阈值分类，因此不能按 Trinary 的直觉解释。</p><h2 id="六、-map-为什么晚启动的订阅者仍能收到" tabindex="-1">六、<code>/map</code> 为什么晚启动的订阅者仍能收到 <a class="header-anchor" href="#六、-map-为什么晚启动的订阅者仍能收到" aria-label="Permalink to &quot;六、\`/map\` 为什么晚启动的订阅者仍能收到&quot;">​</a></h2><p>Map Server 的 OccupancyGrid Publisher 使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KeepLast(1)</span></span>
<span class="line"><span>transient_local</span></span>
<span class="line"><span>reliable</span></span></code></pre></div><p>这相当于 ROS 1 的 latched Topic：发布者保留最近一份地图，之后加入且 QoS 兼容的订阅者仍能收到。</p><p><img src="`+r+`" alt="图 5：Topic、GetMap 与 LoadMap 三条运行期接口"></p><p>这一设计很适合静态地图。地图通常只在 activate 或换图后发布一次，不需要持续高频发送。</p><p>但 transient local 不是“所有订阅者无条件收到”。订阅端 QoS 必须兼容；发布者进程退出后，它保存的历史样本也随之消失。</p><h2 id="七、getmap-从缓存同步取图" tabindex="-1">七、GetMap：从缓存同步取图 <a class="header-anchor" href="#七、getmap-从缓存同步取图" aria-label="Permalink to &quot;七、GetMap：从缓存同步取图&quot;">​</a></h2><p><code>&lt;node_name&gt;/map</code> 是 <code>nav_msgs/srv/GetMap</code> 服务。</p><p>回调不重新读磁盘，而是直接执行：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response-&gt;map </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg_;</span></span></code></pre></div><p>因此 GetMap 返回的是当前缓存快照，速度快，但内容取决于最近一次 configure 预加载或 LoadMap 成功结果。</p><p>回调只在 Lifecycle 状态为 ACTIVE 时提供地图。非 active 状态会警告并直接返回，不把未准备好的缓存暴露给调用方。</p><p>需要注意：GetMap 服务名默认是 <code>map_server/map</code>，而 Topic 默认是 <code>/map</code>。两者消息类型和调用方式完全不同，排障时不能只看到名字里都有 <code>map</code> 就混为一谈。</p><h2 id="八、loadmap-运行中换图的原子主链" tabindex="-1">八、LoadMap：运行中换图的原子主链 <a class="header-anchor" href="#八、loadmap-运行中换图的原子主链" aria-label="Permalink to &quot;八、LoadMap：运行中换图的原子主链&quot;">​</a></h2><p><code>&lt;node_name&gt;/load_map</code> 接收 <code>nav2_msgs/srv/LoadMap</code>，请求核心字段是 <code>map_url</code>。</p><p>只有 ACTIVE 状态才允许加载。非 active 时返回：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RESULT_UNDEFINED_FAILURE</span></span></code></pre></div><p>active 状态下重新执行完整的 YAML → image → OccupancyGrid 转换。成功后依次执行以下操作。</p><h3 id="_8-1-更新地图缓存" tabindex="-1">8.1 更新地图缓存 <a class="header-anchor" href="#_8-1-更新地图缓存" aria-label="Permalink to &quot;8.1 更新地图缓存&quot;">​</a></h3><p>更新 <code>msg_</code> 缓存。</p><h3 id="_8-2-标记地图可用" tabindex="-1">8.2 标记地图可用 <a class="header-anchor" href="#_8-2-标记地图可用" aria-label="Permalink to &quot;8.2 标记地图可用&quot;">​</a></h3><p>设置 <code>map_available_=true</code>。</p><h3 id="_8-3-写入-loadmap-response" tabindex="-1">8.3 写入 LoadMap Response <a class="header-anchor" href="#_8-3-写入-loadmap-response" aria-label="Permalink to &quot;8.3 写入 LoadMap Response&quot;">​</a></h3><p>把地图写入 LoadMap Response。</p><h3 id="_8-4-返回成功结果" tabindex="-1">8.4 返回成功结果 <a class="header-anchor" href="#_8-4-返回成功结果" aria-label="Permalink to &quot;8.4 返回成功结果&quot;">​</a></h3><p>返回 <code>RESULT_SUCCESS</code>。</p><h3 id="_8-5-发布新地图" tabindex="-1">8.5 发布新地图 <a class="header-anchor" href="#_8-5-发布新地图" aria-label="Permalink to &quot;8.5 发布新地图&quot;">​</a></h3><p>立即发布新的 <code>/map</code>。</p><p>失败状态被细分为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RESULT_MAP_DOES_NOT_EXIST</span></span>
<span class="line"><span>RESULT_INVALID_MAP_METADATA</span></span>
<span class="line"><span>RESULT_INVALID_MAP_DATA</span></span></code></pre></div><p>源码直接把新地图加载到成员 <code>msg_</code>。当前 <code>loadMapFromFile()</code> 只有在完整转换结束时才执行 <code>map = msg</code>，所以常见 YAML 或图片异常不会把半成品写入缓存；服务也不会发布失败地图。</p><p>换图后 AMCL 和 Global Costmap 是否立即形成一致状态，还取决于它们各自怎样处理新地图、定位状态和代价地图重建。LoadMap 成功只证明 Map Server 已完成缓存替换与发布，不等于机器人定位已经自动迁移到新地图。</p><h2 id="九、mapsaver-为什么服务回调里还要单独开-executor" tabindex="-1">九、MapSaver：为什么服务回调里还要单独开 Executor <a class="header-anchor" href="#九、mapsaver-为什么服务回调里还要单独开-executor" aria-label="Permalink to &quot;九、MapSaver：为什么服务回调里还要单独开 Executor&quot;">​</a></h2><p><code>MapSaver</code> 提供 <code>&lt;node_name&gt;/save_map</code> 服务。默认节点名为 <code>map_saver</code>，所以常见服务路径是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/map_saver/save_map</span></span></code></pre></div><p>保存不是直接读取 Map Server 的成员缓存。MapSaver 与 MapServer 是两个独立节点，它只能订阅请求指定的地图 Topic。</p><p><img src="`+d+`" alt="图 6：OccupancyGrid 反向保存链"></p><h3 id="_9-1-补齐保存参数" tabindex="-1">9.1 补齐保存参数 <a class="header-anchor" href="#_9-1-补齐保存参数" aria-label="Permalink to &quot;9.1 补齐保存参数&quot;">​</a></h3><p>SaveMap Request 可以指定：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map_topic</span></span>
<span class="line"><span>map_url</span></span>
<span class="line"><span>image_format</span></span>
<span class="line"><span>map_mode</span></span>
<span class="line"><span>free_thresh</span></span>
<span class="line"><span>occupied_thresh</span></span></code></pre></div><p>未指定 Topic 时使用 <code>map</code>。阈值为 0 时使用节点参数默认值 0.25 和 0.65。无法识别的 mode 会退回 trinary。</p><p>输出文件名前缀为空时，<code>map_io</code> 生成 <code>map_&lt;系统时间秒&gt;</code>。Scale 未指定格式时默认 PNG，其他模式默认 PGM。</p><h3 id="_9-2-临时订阅地图" tabindex="-1">9.2 临时订阅地图 <a class="header-anchor" href="#_9-2-临时订阅地图" aria-label="Permalink to &quot;9.2 临时订阅地图&quot;">​</a></h3><p>每次保存请求都会创建一个临时 OccupancyGrid 订阅器。默认启用 transient local、reliable、KeepLast(1)，因此即使 <code>/map</code> 很早以前只发布过一次，也能取得发布者保留的最近样本。</p><p>SaveMap 服务回调本身正在某个 executor 中运行。如果临时订阅仍放在同一个互斥执行上下文里，服务等待消息时可能阻塞订阅回调。</p><p>因此代码创建独立的 <code>MutuallyExclusive</code> callback group，再交给局部 <code>SingleThreadedExecutor</code>，调用 <code>spin_until_future_complete()</code>，等待地图到达或超过 <code>save_map_timeout</code>。</p><p>收到消息后立即释放临时订阅，后续只进行文件转换。</p><h3 id="_9-3-occupancygrid-反向生成图片" tabindex="-1">9.3 OccupancyGrid 反向生成图片 <a class="header-anchor" href="#_9-3-occupancygrid-反向生成图片" aria-label="Permalink to &quot;9.3 OccupancyGrid 反向生成图片&quot;">​</a></h3><p>保存参数必须满足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阈值关系：0.0 ≤ free_thresh &lt; occupied_thresh ≤ 1.0</span></span></code></pre></div><p>图片格式不可写时回退到 PNG。推荐格式是 BMP、PGM 和 PNG。</p><p>随后逐栅格执行与加载方向对应的像素映射，并再次翻转 Y 轴。最终生成两个文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;map_url&gt;.&lt;image_format&gt;</span></span>
<span class="line"><span>&lt;map_url&gt;.yaml</span></span></code></pre></div><p>YAML 中写入图片文件名、模式、分辨率、原点 x／y／yaw、<code>negate: 0</code> 和两个阈值。</p><p>保存超时、订阅失败、参数非法或写盘异常，SaveMap Response 都返回 false。</p><h2 id="十、mapsaver-cli-与-server-是两条入口" tabindex="-1">十、MapSaver CLI 与 Server 是两条入口 <a class="header-anchor" href="#十、mapsaver-cli-与-server-是两条入口" aria-label="Permalink to &quot;十、MapSaver CLI 与 Server 是两条入口&quot;">​</a></h2><p><code>map_saver_server</code> 是长期运行的 Lifecycle 服务节点，适合由 SLAM 或业务系统反复调用。</p><p><code>map_saver_cli</code> 是一次性命令入口。它解析命令行参数，构造 MapSaver，手动调用 configure，然后直接执行 <code>saveMapTopicToFile()</code>；保存完成后退出。</p><p>两者最终复用相同的订阅和 <code>map_io</code> 写盘链，因此图片模式、阈值和超时规则一致。</p><h2 id="十一、costmapfilterinfoserver-在这个包里的位置" tabindex="-1">十一、CostmapFilterInfoServer 在这个包里的位置 <a class="header-anchor" href="#十一、costmapfilterinfoserver-在这个包里的位置" aria-label="Permalink to &quot;十一、CostmapFilterInfoServer 在这个包里的位置&quot;">​</a></h2><p>这个节点不发布 OccupancyGrid，也不读取地图图片。</p><p>它发布 <code>nav2_msgs/msg/CostmapFilterInfo</code>，内容包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type</span></span>
<span class="line"><span>filter_mask_topic</span></span>
<span class="line"><span>base</span></span>
<span class="line"><span>multiplier</span></span></code></pre></div><p>Publisher 同样使用 KeepLast(1)、transient local 和 reliable，并在 activate 时发布一次。</p><p>它告诉 Costmap Filter 如何解释另一个 mask Topic。mask 本身通常由独立 Map Server 以 OccupancyGrid 形式提供。因此过滤器场景常见两条并行数据流：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter mask OccupancyGrid → 过滤区域数值</span></span>
<span class="line"><span>CostmapFilterInfo         → mask topic 名与换算参数</span></span></code></pre></div><h2 id="十二、地图发布后流向哪里" tabindex="-1">十二、地图发布后流向哪里 <a class="header-anchor" href="#十二、地图发布后流向哪里" aria-label="Permalink to &quot;十二、地图发布后流向哪里&quot;">​</a></h2><h3 id="_12-1-amcl" tabindex="-1">12.1 AMCL <a class="header-anchor" href="#_12-1-amcl" aria-label="Permalink to &quot;12.1 AMCL&quot;">​</a></h3><p>AMCL 使用静态地图构建似然场或距离场，并结合 LaserScan 和里程计估计 <code>map → odom</code>。</p><p>Map Server 只提供地图本体，不发布 <code>map → odom</code> TF。RViz2 出现 “No transform from map” 时，不能把 TF 缺失归因成 Map Server 没有发布坐标变换。</p><h3 id="_12-2-global-costmap-staticlayer" tabindex="-1">12.2 Global Costmap StaticLayer <a class="header-anchor" href="#_12-2-global-costmap-staticlayer" aria-label="Permalink to &quot;12.2 Global Costmap StaticLayer&quot;">​</a></h3><p>StaticLayer 订阅 <code>/map</code>，把 OccupancyGrid 转成全局代价地图的静态层。之后 Planner Server 在融合后的 global costmap 上规划路径。</p><p>Map Server 的 <code>free_thresh</code> 和 <code>occupied_thresh</code> 决定最初的 OccupancyGrid 分类；StaticLayer 的参数又决定这些值怎样映射成 costmap 代价。两层阈值不能混为一组。</p><h3 id="_12-3-rviz2-和业务节点" tabindex="-1">12.3 RViz2 和业务节点 <a class="header-anchor" href="#_12-3-rviz2-和业务节点" aria-label="Permalink to &quot;12.3 RViz2 和业务节点&quot;">​</a></h3><p>RViz2 的 Map Display 直接订阅 OccupancyGrid。业务程序可以订阅 <code>/map</code>，也可以调用 GetMap 获取缓存快照。</p><p>Topic 更适合监听换图；Service 更适合按需同步查询当前地图。</p><h2 id="十三、最常见的七个排障边界" tabindex="-1">十三、最常见的七个排障边界 <a class="header-anchor" href="#十三、最常见的七个排障边界" aria-label="Permalink to &quot;十三、最常见的七个排障边界&quot;">​</a></h2><h3 id="_13-1-yaml-filename-为空不等于配置失败" tabindex="-1">13.1 <code>yaml_filename</code> 为空不等于配置失败 <a class="header-anchor" href="#_13-1-yaml-filename-为空不等于配置失败" aria-label="Permalink to &quot;13.1 \`yaml_filename\` 为空不等于配置失败&quot;">​</a></h3><p><code>yaml_filename</code> 为空不代表 Map Server 配置失败，它可能在等待 LoadMap；但 active 后没有缓存时不会自动发布空地图。</p><h3 id="_13-2-yaml-可打开不等于地图有效" tabindex="-1">13.2 YAML 可打开不等于地图有效 <a class="header-anchor" href="#_13-2-yaml-可打开不等于地图有效" aria-label="Permalink to &quot;13.2 YAML 可打开不等于地图有效&quot;">​</a></h3><p>图片路径、图片编码或像素读取错误属于 <code>INVALID_MAP_DATA</code>。</p><h3 id="_13-3-相对图片路径以-yaml-目录为基准" tabindex="-1">13.3 相对图片路径以 YAML 目录为基准 <a class="header-anchor" href="#_13-3-相对图片路径以-yaml-目录为基准" aria-label="Permalink to &quot;13.3 相对图片路径以 YAML 目录为基准&quot;">​</a></h3><p>相对图片路径以 YAML 所在目录为基准，不以 launch 文件或当前 shell 目录为基准。</p><h3 id="_13-4-map-不持续刷新是正常现象" tabindex="-1">13.4 <code>/map</code> 不持续刷新是正常现象 <a class="header-anchor" href="#_13-4-map-不持续刷新是正常现象" aria-label="Permalink to &quot;13.4 \`/map\` 不持续刷新是正常现象&quot;">​</a></h3><p><code>/map</code> 是 transient-local 静态数据，不是传感器流。</p><h3 id="_13-5-优先核对历史地图-qos" tabindex="-1">13.5 优先核对历史地图 QoS <a class="header-anchor" href="#_13-5-优先核对历史地图-qos" aria-label="Permalink to &quot;13.5 优先核对历史地图 QoS&quot;">​</a></h3><p>订阅不到历史地图时先核对 QoS，而不是反复重启 Map Server。</p><h3 id="_13-6-map-server-active-不等于定位-active" tabindex="-1">13.6 Map Server Active 不等于定位 Active <a class="header-anchor" href="#_13-6-map-server-active-不等于定位-active" aria-label="Permalink to &quot;13.6 Map Server Active 不等于定位 Active&quot;">​</a></h3><p>AMCL、Lifecycle Manager、TF 和初始位姿仍是独立链路。</p><h3 id="_13-7-mapsaver-必须具备完整保存条件" tabindex="-1">13.7 MapSaver 必须具备完整保存条件 <a class="header-anchor" href="#_13-7-mapsaver-必须具备完整保存条件" aria-label="Permalink to &quot;13.7 MapSaver 必须具备完整保存条件&quot;">​</a></h3><p>保存地图时 MapSaver 必须在超时前收到兼容 QoS 的 OccupancyGrid，并且进程具有目标目录写权限。</p><h2 id="十四、建议的观测顺序" tabindex="-1">十四、建议的观测顺序 <a class="header-anchor" href="#十四、建议的观测顺序" aria-label="Permalink to &quot;十四、建议的观测顺序&quot;">​</a></h2><p>遇到地图不显示或换图失败，可以按下面顺序检查。</p><h3 id="_14-1-检查-map-server-lifecycle" tabindex="-1">14.1 检查 Map Server Lifecycle <a class="header-anchor" href="#_14-1-检查-map-server-lifecycle" aria-label="Permalink to &quot;14.1 检查 Map Server Lifecycle&quot;">​</a></h3><p>确认 <code>map_server</code> Lifecycle 是否 active。</p><h3 id="_14-2-检查基础参数" tabindex="-1">14.2 检查基础参数 <a class="header-anchor" href="#_14-2-检查基础参数" aria-label="Permalink to &quot;14.2 检查基础参数&quot;">​</a></h3><p>确认 <code>yaml_filename</code>、<code>topic_name</code>、<code>frame_id</code> 是否符合预期。</p><h3 id="_14-3-检查-yaml-与图片路径" tabindex="-1">14.3 检查 YAML 与图片路径 <a class="header-anchor" href="#_14-3-检查-yaml-与图片路径" aria-label="Permalink to &quot;14.3 检查 YAML 与图片路径&quot;">​</a></h3><p>确认 YAML 的 <code>image</code> 相对路径和字段是否有效。</p><h3 id="_14-4-检查-map-接口" tabindex="-1">14.4 检查 <code>/map</code> 接口 <a class="header-anchor" href="#_14-4-检查-map-接口" aria-label="Permalink to &quot;14.4 检查 \`/map\` 接口&quot;">​</a></h3><p>确认 <code>/map</code> 的类型、发布者数量和 QoS 是否正确。</p><h3 id="_14-5-检查-getmap-结果" tabindex="-1">14.5 检查 GetMap 结果 <a class="header-anchor" href="#_14-5-检查-getmap-结果" aria-label="Permalink to &quot;14.5 检查 GetMap 结果&quot;">​</a></h3><p>确认 GetMap 是否返回有效 <code>width／height／resolution</code>。</p><h3 id="_14-6-检查-loadmap-错误类型" tabindex="-1">14.6 检查 LoadMap 错误类型 <a class="header-anchor" href="#_14-6-检查-loadmap-错误类型" aria-label="Permalink to &quot;14.6 检查 LoadMap 错误类型&quot;">​</a></h3><p>确认 LoadMap Response 的 <code>result</code> 具体是哪类错误。</p><h3 id="_14-7-检查下游地图接收" tabindex="-1">14.7 检查下游地图接收 <a class="header-anchor" href="#_14-7-检查下游地图接收" aria-label="Permalink to &quot;14.7 检查下游地图接收&quot;">​</a></h3><p>确认 AMCL 与 StaticLayer 是否收到新地图。</p><h3 id="_14-8-检查-tf-链" tabindex="-1">14.8 检查 TF 链 <a class="header-anchor" href="#_14-8-检查-tf-链" aria-label="Permalink to &quot;14.8 检查 TF 链&quot;">​</a></h3><p>确认 <code>map → odom → base_link</code> TF 是否完整。</p><p>不要只看 RViz2 中“有没有一张图”。同样的空白界面，可能来自文件读取失败、Lifecycle 未激活、QoS 不兼容、固定坐标系错误或 TF 缺失。</p><h2 id="十五、结语" tabindex="-1">十五、结语 <a class="header-anchor" href="#十五、结语" aria-label="Permalink to &quot;十五、结语&quot;">​</a></h2><p><code>nav2_map_server</code> 的本质，是地图数据格式和 ROS 运行时之间的边界层。</p><p>正向链路把静态文件变成可共享的地图状态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YAML + image</span></span>
<span class="line"><span>→ 像素占用解释</span></span>
<span class="line"><span>→ OccupancyGrid 缓存</span></span>
<span class="line"><span>→ transient-local /map</span></span>
<span class="line"><span>→ 定位、代价地图和可视化</span></span></code></pre></div><p>反向链路把运行时地图重新固化为文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OccupancyGrid Topic</span></span>
<span class="line"><span>→ MapSaver 临时订阅</span></span>
<span class="line"><span>→ 像素反向映射</span></span>
<span class="line"><span>→ image + YAML</span></span></code></pre></div><p>理解这两条链，就能把“地图不显示”拆成具体的数据层、生命周期状态、ROS 接口和下游消费问题，而不是把所有故障都笼统归因给一张 PGM 图片。</p>`,210)])])}const f=e(h,[["render",m]]);export{y as __pageData,f as default};
